def rangecalc(x, y=None, pad=0.05):
    mn = np.nanmin([np.nanmin(x), np.nanmin(y)])
    mx = np.nanmax([np.nanmax(x), np.nanmax(y)])
    rn = mx - mn

    return (mn - pad * rn, mx + pad * rn)

