def op_to_words(item):
    sdicts = [
        {"==": ""},
        {">=": " or newer"},
        {">": "newer than "},
        {"<=": " or older"},
        {"<": "older than "},
        {"!=": "except "},
    ]
    for sdict in sdicts:
        prefix = list(sdict.keys())[0]
        suffix = sdict[prefix]
        if item.startswith(prefix):
            if prefix == "==":
                return item[2:]
            if prefix == "!=":
                return suffix + item[2:]
            if prefix in [">", "<"]:
                return suffix + item[1:]
            return item[2:] + suffix
    raise RuntimeError("Inequality not supported")

def remove(self, mol):
        log.debug('Running FragmentRemover')
        # Iterate FragmentPatterns and remove matching fragments
        for frag in self.fragments:
            # If nothing is left or leave_last and only one fragment, end here
            if mol.GetNumAtoms() == 0 or (self.leave_last and len(Chem.GetMolFrags(mol)) <= 1):
                break
            # Apply removal for this FragmentPattern
            removed = Chem.DeleteSubstructs(mol, frag.smarts, onlyFrags=True)
            if not mol.GetNumAtoms() == removed.GetNumAtoms():
                log.info('Removed fragment: %s', frag.name)
            if self.leave_last and removed.GetNumAtoms() == 0:
                # All the remaining fragments match this pattern - leave them all
                break
            mol = removed
        return mol

def sum_rightmost_ndims_preserving_shape(x, ndims):
  x = tf.convert_to_tensor(value=x)
  if x.shape.ndims is not None:
    axes = tf.range(x.shape.ndims - ndims, x.shape.ndims)
  else:
    axes = tf.range(tf.rank(x) - ndims, tf.rank(x))
  return tf.reduce_sum(input_tensor=x, axis=axes)

