def duplicates(*iterables, **kwargs):
    key = kwargs.pop('key', lambda x: x)
    assert not kwargs
    zipped = more_itertools.collate(*iterables, key=key)
    grouped = itertools.groupby(zipped, key=key)
    groups = (
        tuple(g)
        for k, g in grouped
    )

    def has_dupes(group):
        return len(group) > 1
    return filter(has_dupes, groups)

