def parse_response(self, response):
        payload = None
        try:
            if isinstance(response.json, collections.Callable):
                payload = response.json()
            else:
                # json isn't callable in old versions of requests
                payload = response.json
        except ValueError:
            # response does not have JSON content
            payload = response.content

        if not self._raise_errors:
            return payload
        else:
            if response.status_code == 401:
                raise AuthenticationError(payload['message'])
            elif response.status_code == 500:
                raise ServerError(payload['message'])
            elif isinstance(payload, dict) and not payload['success']:
                raise APIError(payload['message'])
            else:
                return payload

def serialCmdPwdAuth(self, password_str):
        result = False
        try:
            req_start = "0150310228" + binascii.hexlify(password_str) + "2903"
            req_crc = self.calc_crc16(req_start[2:].decode("hex"))
            req_str = req_start + req_crc
            self.m_serial_port.write(req_str.decode("hex"))
            if self.m_serial_port.getResponse(self.getContext()).encode("hex") == "06":
                ekm_log("Password accepted (" + self.getContext() + ")")
                result = True
            else:
                ekm_log("Password call failure no 06(" + self.getContext() + ")")
        except:
            ekm_log("Password call failure by exception(" + self.getContext() + ")")

            ekm_log(traceback.format_exc(sys.exc_info()))

        return result

