                     "writing manifest file '%s'" % self.manifest)

def list_to_string(l = range(200), width = 40, indent = "  "):
    l = [str(v) + "," for v in l]
    counter = 0
    out = "" + indent
    for w in l:
        s = len(w)
        if counter + s > width: 
            out += "\n" + indent
            counter = 0
        out += w
        counter += s
    return out.strip(",")

def lowercase_ext(filename):
