def add_cert(self, cert):
        if not isinstance(cert, X509):
            raise TypeError()

        # As of OpenSSL 1.1.0i adding the same cert to the store more than
        # once doesn't cause an error. Accordingly, this code now silences
        # the error for OpenSSL < 1.1.0i as well.
        if _lib.X509_STORE_add_cert(self._store, cert._x509) == 0:
            code = _lib.ERR_peek_error()
            err_reason = _lib.ERR_GET_REASON(code)
            _openssl_assert(
                err_reason == _lib.X509_R_CERT_ALREADY_IN_HASH_TABLE
            )
            _lib.ERR_clear_error()

def _parse_match(self, match):
        if not match:
            if self.default:
                return self.default
            else:
                raise NothingMatchedError(
                    f"Extract `{self._re_select}` error, "
                    f"please check selector or set parameter named `default`")
        else:
            string = match.group()
            groups = match.groups()
            group_dict = match.groupdict()
            if group_dict:
                return group_dict
            if groups:
                return groups[0] if len(groups) == 1 else groups
            return string

def build(self, pre=None, shortest=False):
        if pre is None:
            pre = []

        if self.value is not None and rand.maybe():
            return utils.val(self.value, pre, shortest=shortest)

        if self.min == self.max:
