def _parse_list_nested_recursive(
        cls, data, path, iterators, list_vars, cur_vars=None
    ):
        cur_vars = dict(cur_vars) if cur_vars else {}
        if path:
            p = path[0]
            path = path[1:]
        else:
            for _ in data:
                list_vars.append(cur_vars)
            iterators.append(data)
            return data

        if p.startswith("?"):
            for x in data:
                key, var_path = p.split(".")
                cur_vars.update({key.lstrip("?"): x.xpath(var_path)[0].text})
                cls._parse_list_nested_recursive(
                    x, path, iterators, list_vars, cur_vars
                )
        else:
            x = data.xpath(p)
            cls._parse_list_nested_recursive(x, path, iterators, list_vars, cur_vars)

def transform(self, fn, dtype=None, *args, **kwargs):
        rdd = self._rdd.map(fn)

        if dtype is None:
            return self.__class__(rdd, noblock=True, **self.get_params())
        if dtype is np.ndarray:
            return ArrayRDD(rdd, bsize=self.bsize, noblock=True)
        elif dtype is sp.spmatrix:
            return SparseRDD(rdd, bsize=self.bsize, noblock=True)
        else:
            return BlockRDD(rdd, bsize=self.bsize, dtype=dtype, noblock=True)

