def parse_sv_frequencies(variant):
    frequency_keys = [
        'clingen_cgh_benignAF',
        'clingen_cgh_benign',
        'clingen_cgh_pathogenicAF',
        'clingen_cgh_pathogenic',
        'clingen_ngi',
        'clingen_ngiAF',
        'swegen',
        'swegenAF',
        'decipherAF',
        'decipher'
    ]
    sv_frequencies = {}

    for key in frequency_keys:
        value = variant.INFO.get(key, 0)
        if 'AF' in key:
            value = float(value)
        else:
            value = int(value)
        if value > 0:
            sv_frequencies[key] = value
    return sv_frequencies

