def check_compressed_file_type(filepath):
    def compressed_file_type(content):
        magic_dict = {
            b'\x1f\x8b\x08': 'gz',
            b'\x42\x5a\x68': 'bz2',
            b'PK\x03\x04': 'zip'
        }

        for magic, filetype in magic_dict.items():
            if content.startswith(magic):
                return filetype

        return None

    with open(filepath, mode='rb') as f:
        magic_number = f.read(4)
    return compressed_file_type(magic_number)

def flame_map(self):
        flame_map = {}
        _, stack_counts = self.live_data_copy()
        for stack, count in stack_counts.items():
            root = stack[-2].co_name
            stack_elements = []
            for i in range(len(stack)):
                if type(stack[i]) in (int, long):
                    continue
                code = stack[i]
                stack_elements.append("{0}`{1}`{2}".format(
                    root, code.co_filename, code.co_name))
            flame_key = ';'.join(stack_elements)
            flame_map.setdefault(flame_key, 0)
            flame_map[flame_key] += count
        return flame_map

