def word_break(el, max_width=40,
               avoid_elements=_avoid_word_break_elements,
               avoid_classes=_avoid_word_break_classes,
               break_character=unichr(0x200b)):
    # Character suggestion of &#8203 comes from:
    #   http://www.cs.tut.fi/~jkorpela/html/nobr.html
    if el.tag in _avoid_word_break_elements:
        return
    class_name = el.get('class')
    if class_name:
        dont_break = False
        class_name = class_name.split()
        for avoid in avoid_classes:
            if avoid in class_name:
                dont_break = True
                break
        if dont_break:
            return
    if el.text:
        el.text = _break_text(el.text, max_width, break_character)
    for child in el:
        word_break(child, max_width=max_width,
                   avoid_elements=avoid_elements,
                   avoid_classes=avoid_classes,
                   break_character=break_character)
        if child.tail:
            child.tail = _break_text(child.tail, max_width, break_character)

def getResponse(self, context=""):
        waits = 0  # allowed interval counter
        response_str = ""  # returned bytes in string default
        try:
            waits = 0  # allowed interval counter
            while (waits < self.m_max_waits):
                bytes_to_read = self.m_ser.inWaiting()
                if bytes_to_read > 0:
                    next_chunk = str(self.m_ser.read(bytes_to_read)).encode('ascii', 'ignore')
                    response_str += next_chunk
                    if (len(response_str) == 255):
                        time.sleep(self.m_force_wait)
                        return response_str
                    if (len(response_str) == 1) and (response_str.encode('hex') == '06'):
                        time.sleep(self.m_force_wait)
                        return response_str
                else:  # hang out -- half shortest expected interval (50 ms)
                    waits += 1
                    time.sleep(self.m_force_wait)
            response_str = ""

        except:
            ekm_log(traceback.format_exc(sys.exc_info()))

        return response_str

