def restore(folder):
    if os.path.isdir(folder):
        bail('a folder of the same name already exists!')

    pattern = os.path.join(PROJ_ARCHIVE, '*', '*', folder)
    matches = glob.glob(pattern)
    if not matches:
        bail('no project matches: ' + folder)

    if len(matches) > 1:
        print('Warning: multiple matches, picking the most recent',
              file=sys.stderr)

    source = sorted(matches)[-1]
    print(source, '-->', folder)
    shutil.move(source, '.')

def cached(method) -> property:
    name = "_" + method.__name__

    @property
    def wrapper(self):
        try:
            return getattr(self, name)
        except AttributeError:
            val = method(self)
            setattr(self, name, val)
            return val

    return wrapper

def spawn(self, cmd, stdin_content="", stdin=False, shell=False, timeout=2):
        try:
            if type(cmd) != list:
                raise PJFInvalidType(type(cmd), list)
            if type(stdin_content) != str:
                raise PJFInvalidType(type(stdin_content), str)
            if type(stdin) != bool:
                raise PJFInvalidType(type(stdin), bool)
            self._in = stdin_content
            try:
                self.process = subprocess.Popen(cmd, stdout=PIPE, stderr=PIPE, stdin=PIPE, shell=shell)
                self.finish_read(timeout, stdin_content, stdin)
                if self.process.poll() is not None:
                    self.close()
            except KeyboardInterrupt:
                return
        except OSError:
            raise PJFProcessExecutionError("Binary <%s> does not exist" % cmd[0])
        except Exception as e:
            raise PJFBaseException(e.message if hasattr(e, "message") else str(e))

