def fetch_streams_with_retry(plugin, interval, count):

    try:
        streams = fetch_streams(plugin)
    except PluginError as err:
        log.error(u"{0}", err)
        streams = None

    if not streams:
        log.info("Waiting for streams, retrying every {0} "
                 "second(s)", interval)
    attempts = 0

    while not streams:
        sleep(interval)

        try:
            streams = fetch_streams(plugin)
        except FatalPluginError as err:
            raise
        except PluginError as err:
            log.error(u"{0}", err)

        if count > 0:
            attempts += 1
            if attempts >= count:
                break

    return streams

