def _convert_to_bits(a_list, bits):
    new_list = []
    for item in a_list:
        if isinstance(item, (int, slice)):
            # eg. circuit.h(2)
            # eg. circuit.h(slice(0, 2))
            try:
                new_list.append(bits[item])
            except IndexError:
                raise QiskitError("The integer param is out of range")
        elif isinstance(item, list):
            # eg. circuit.h([0, 2])
            new_list.append(_convert_to_bits(item, bits))
        elif isinstance(item, range):
            # eg. circuit.h(range(0, 2))
            new_list.append(_convert_to_bits([index for index in item], bits))
        else:
            new_list.append(item)
    return new_list

def _resolve_path(path, manager_dict):
    path = normalize_api_path(path)
    parts = path.split('/')

    # Try to find a sub-manager for the first subdirectory.
    mgr = manager_dict.get(parts[0])
    if mgr is not None:
        return parts[0], mgr, '/'.join(parts[1:])

    # Try to find use the root manager, if one was supplied.
    mgr = manager_dict.get('')
    if mgr is not None:
        return '', mgr, path

    raise HTTPError(
        404,
        "Couldn't resolve path [{path}] and "
        "no root manager supplied!".format(path=path)
    )

